    "app.test.ts": "import { get, lastReply } from './app'\n\nconst settings = { homeAssistant: { url: 'http://ha.local:8123/', accessToken: 'tok' } }\n\nbeforeEach(() => {\n  lastReply.at = 0\n  lastReply.body = ''\n})\n\ndescribe('haSensor', () => {\n  it('fetches the entity state with the token and returns it', () => {\n    const http = mock.httpRequest(() => mock.json({ entity_id: 'sensor.temp', state: '21.5' }))\n    const state = get(makeApp({ settings, config: { entityId: ' sensor.temp ' } }))\n    expect(state).toEqual({ entity_id: 'sensor.temp', state: '21.5' })\n    expect(http).toHaveBeenCalledTimes(1)\n    expect(http.calls[0][0]).toBe('http://ha.local:8123/api/states/sensor.temp')\n    expect(http.calls[0][1]).toMatchObject({ headers: { Authorization: 'Bearer tok' }, timeoutMs: 10000 })\n  })\n\n  it('answers from the last reply for a second within the same run', () => {\n    const http = mock.httpRequest(() => mock.json({ state: 'on' }))\n    get(makeApp({ settings, config: { entityId: 'light.desk' } }))\n    expect(get(makeApp({ settings, config: { entityId: 'light.desk' } }))).toEqual({ state: 'on' })\n    expect(http).toHaveBeenCalledTimes(1)\n  })\n\n  it('reports missing settings and a bad entity id without a request', () => {\n    const http = mock.httpRequest()\n    const error = mock.error()\n    expect(get(makeApp({ settings: {}, config: { entityId: 'sensor.temp' } }))).toEqual({\n      error: 'Please provide a Home Assistant URL in the settings.',\n    })\n    expect(get(makeApp({ settings: { homeAssistant: { url: 'x' } }, config: { entityId: 'sensor.temp' } }))).toMatchObject({\n      error: 'Please provide a Home Assistant access token in the settings.',\n    })\n    expect(get(makeApp({ settings, config: { entityId: 'Sensor Temp' } })).error).toContain('Invalid Home Assistant entity id')\n    expect(http).not.toHaveBeenCalled()\n    expect(error).toHaveBeenCalledTimes(3)\n  })\n\n  it('reports HTTP and transport failures', () => {\n    mock.httpRequest(() => mock.response(404, 'nope'))\n    expect(get(makeApp({ settings, config: { entityId: 'sensor.temp' } }))).toEqual({\n      error: 'Error fetching Home Assistant status: HTTP 404: nope',\n    })\n    mock.httpRequest(() => ({ status: 0, error: 'timeout' }))\n    expect(get(makeApp({ settings, config: { entityId: 'sensor.temp' } })).error).toBe(\n      'Error fetching Home Assistant status: timeout'\n    )\n    mock.httpRequest(() => mock.response(200, 'not json'))\n    expect(get(makeApp({ settings, config: { entityId: 'sensor.temp' } })).error).toContain('Error fetching Home Assistant status')\n  })\n})\n",
    "app.ts": "// The state of one Home Assistant entity (GET /api/states/<entity_id>).\nexport const lastReply = { at: 0, body: '' }\n\nfunction errorReply(error) {\n  frameos.error(error)\n  return { error }\n}\n\nexport function get(app) {\n  const url = frameos.getSetting('homeAssistant', 'url')\n  if (!url) return errorReply('Please provide a Home Assistant URL in the settings.')\n  const token = frameos.getSetting('homeAssistant', 'accessToken')\n  if (!token) return errorReply('Please provide a Home Assistant access token in the settings.')\n  if (lastReply.body && lastReply.at + 1000 > Date.now()) return JSON.parse(lastReply.body)\n\n  const id = (app.config.entityId ?? '').trim()\n  if (!/^[a-z0-9_]+\\.[a-z0-9_]+$/.test(id))\n    return errorReply(\n      `Invalid Home Assistant entity id \"${id}\": expected <domain>.<object_id> using only a-z, 0-9 and _.`\n    )\n  const stateUrl = `${url.endsWith('/') ? url.slice(0, -1) : url}/api/states/${id}`\n  if (app.config.debug) frameos.log(`Fetching Home Assistant status from ${stateUrl}`)\n  const { status, body, error } = frameos.httpRequest(stateUrl, {\n    headers: { Authorization: `Bearer ${token}`, Accept: 'application/json', 'Accept-Encoding': 'identity' },\n    timeoutMs: 10000,\n  })\n  const fail = (why) => errorReply(`Error fetching Home Assistant status: ${why}`)\n  if (!status) return fail(error)\n  if (status >= 400) return fail(`HTTP ${status}: ${body}`)\n  let state\n  try {\n    state = JSON.parse(body)\n  } catch (e) {\n    return fail(e.message)\n  }\n  lastReply.at = Date.now()\n  lastReply.body = body\n  if (app.config.debug) frameos.log(JSON.stringify(state))\n  return state\n}\n",
    "config.json": "{\n  \"name\": \"Home Assistant Sensor\",\n  \"description\": \"Get the state of a Home Assistant entity\",\n  \"category\": \"data\",\n  \"version\": \"1.0.0\",\n  \"settings\": [\"homeAssistant\"],\n  \"fields\": [\n    { \"markdown\": \"Find the [entity id here](http://homeassistant.local:8123/config/entities)\" },\n    { \"name\": \"entityId\", \"type\": \"text\", \"required\": true, \"label\": \"Entity ID\", \"placeholder\": \"sensor.temperature\" },\n    { \"name\": \"debug\", \"type\": \"boolean\", \"value\": \"false\", \"label\": \"Debug logging\" }\n  ],\n  \"output\": [{ \"name\": \"state\", \"type\": \"json\" }],\n  \"cache\": { \"enabled\": true, \"inputEnabled\": true, \"durationEnabled\": true, \"duration\": \"60\" }\n}\n"
